
import numpy as np
data = {'갈증을 해소할 수 있는 적절한 물건을 흰 상자 위에 올려': [{'position': [0.5852, 0.264, 0.14], 'dimensions': [0.099, 0.06], 'area': 830082.024392, 'rotation_degree': -50.86, 'mask_base64': '', 'score': 0.982, 'id': 'beverage can_1', 'object_name': 'beverage can', 'purpose': 'drink to quench thirst; to be placed on the white box'}, {'position': [np.float64(0.585), np.float64(0.264), 0.06], 'dimensions': [0.158, 0.103], 'area': 975299.144098, 'rotation_degree': -89.44, 'mask_base64': '', 'score': 0.964, 'id': 'white box_3', 'object_name': 'white box', 'purpose': 'target surface to place the beverage can'}], '남아있는 물건들 중 큰 것부터 하나를 흰 상자 오른쪽에 놔': [{'position': [np.float64(0.631), np.float64(0.406), 0.087], 'dimensions': [0.162, 0.085], 'area': 1196660.275629, 'rotation_degree': -12.45, 'mask_base64': '', 'score': 0.961, 'id': 'beverage can_1', 'object_name': 'beverage can', 'purpose': 'place to the right of the white box'}, {'position': [np.float64(0.583), np.float64(0.262), 0.062], 'dimensions': [0.158, 0.101], 'area': 990083.128248, 'rotation_degree': 89.71, 'mask_base64': '', 'score': 0.959, 'id': 'white box_3', 'object_name': 'white box', 'purpose': 'reference point to place item to the right of'}]}
from typing import Dict, List, Optional

def task_summary_en(data):
    """
    Goal : when action block is more then 1, this func makes llm define left over objects
    Build one English sentence per task from {task: [ {id, purpose, ...}, ... ]}.
    - De-duplicates IDs per task, preserves first-seen order.
    - Formats each item as "id (purpose)" when purpose exists, else "id".
    - Returns newline-joined sentences; never truncates content.
    """
    output_sentences = []

    for task, items in data.items():
        seen_ids = set()
        parts = []

        if isinstance(items, list):
            for item in items:
                # 아이템이 딕셔너리 형태가 아니면 건너뜁니다.
                if not isinstance(item, dict):
                    continue
                
                item_id = item.get("id")
                
                # ID가 없거나 이미 처리한 ID이면 건너뜁니다.
                if not item_id or item_id in seen_ids:
                    continue
                
                seen_ids.add(item_id)
                purpose = item.get("purpose")
                
                # ID와 목적(purpose)을 명확히 분리하는 문자열 형식 생성
                if purpose:
                    parts.append(f"the item '{item_id}' (purpose: {purpose})")
                else:
                    parts.append(f"the item '{item_id}'")

        # 처리된 아이템이 있는지 확인하여 최종 문자열을 조립합니다.
        if not parts:
            used_string = "no items"
        elif len(parts) == 1:
            used_string = parts[0]
        else:
            # 여러 아이템일 경우 쉼표와 'and'를 사용하여 자연스럽게 연결
            used_string = ", ".join(parts[:-1]) + f", and {parts[-1]}"

        # 최종적으로 LLM에게 전달될 자연스러운 문장을 생성합니다.
        # 아이템 개수에 따라 동사(was/were)를 올바르게 사용합니다.
        verb = 'was' if len(parts) <= 1 else 'were'
        output_sentences.append(f"For the task '{task}', {used_string} {verb} used.")
        
    return "\n".join(output_sentences)

# 1) 프롬프트에 바로 넣을 영어 문장 변수
PAST_ACTIONS_EN = task_summary_en(data)

print(PAST_ACTIONS_EN)
